const fs = require('fs');
const path = require('path');
const filePath = path.join(__dirname, 'src', 'data', 'book2.ts');
let content = fs.readFileSync(filePath, 'utf-8');
const esc = s => s.replace(/\\/g, '\\\\').replace(/'/g, "\\'");

const lessons = [
  { id:21, title:'Mad or not?', titleCn:'是不是疯了？', text:['I live near an airport and passing planes can be heard night and day.','The airport was built years ago, but for some reason it could not be used then.','Last year, however, it came into use.','Over a hundred people must have been driven away from their homes by the noise.','I am one of the few people left. Sometimes I think this house will be knocked down by a passing plane.','I have been offered a large sum of money to go away, but I am determined to stay here.'], vocab:[['mad','/mæd/','发疯的'],['reason','/ˈriːzn/','原因'],['sum','/sʌm/','量，金额'],['determined','/dɪˈtɜːmɪnd/','坚定的'],['airport','/ˈeəpɔːt/','机场'],['noise','/nɔɪz/','噪音']], notes:['must have been driven away 表示对过去的推测。','be determined to do 表示决心做某事。','a large sum of money 一大笔钱。'], tags:['被动语态','情态动词'], difficulty:2, summary:'叙述者住在机场附近，飞机噪音不断，但他决心留下来，尽管收到了一大笔搬迁费。', summaryEn:'The narrator lives near an airport and is constantly disturbed by plane noise, but is determined to stay despite being offered money to leave.' },
  { id:22, title:'A glass envelope', titleCn:'玻璃信封', text:['My daughter, Jane, never dreamed of receiving a letter from a girl of her own age in Holland.','Last year, we were travelling across the Channel and Jane put a piece of paper with her name and address into a bottle.','She threw the bottle into the sea. She never thought of it again.','Ten months later, she received a letter from a girl in Holland.','Both girls write to each other regularly now. However, they have decided to use the post office.','Letters will cost a little more, but they will certainly travel faster.'], vocab:[['envelope','/ˈenvələʊp/','信封'],['dream','/driːm/','做梦'],['Channel','/ˈtʃænl/','英吉利海峡'],['address','/əˈdres/','地址'],['regularly','/ˈreɡjələli/','定期地'],['certainly','/ˈsɜːtnli/','无疑地']], notes:['dream of doing 梦想做某事。','never thought of it again 再也没想过这件事。','each other 互相。'], tags:['一般过去时','过去进行时'], difficulty:2, summary:'作者的女儿简在渡过英吉利海峡时把装有姓名地址的瓶子扔进海里，十个月后竟收到了荷兰女孩的来信。', summaryEn:'Jane threw a bottle with her name and address into the sea while crossing the Channel. Ten months later she received a letter from a girl in Holland.' },
  { id:23, title:'A new house', titleCn:'新居', text:['I had a letter from my sister yesterday. She lives in Nigeria.','In her letter, she said that she would come to England next year.','If she comes, she will get a surprise.','We are now living in a beautiful new house in the country.','Work on it had begun before my sister left.','The house was completed five months ago. In my letter, I told her that she could stay with us.'], vocab:[['Nigeria','/naɪˈdʒɪəriə/','尼日利亚'],['surprise','/səˈpraɪz/','惊喜'],['country','/ˈkʌntri/','乡下'],['complete','/kəmˈpliːt/','完成'],['house','/haʊs/','房子'],['letter','/ˈletə/','信']], notes:['she will get a surprise 她会感到惊喜。','work on it had begun 是过去完成时表示在她离开之前就已开始。','told her that she could stay 宾语从句。'], tags:['条件句','过去完成时'], difficulty:2, summary:'作者告诉在尼日利亚的妹妹，他们已经在乡下建好了一栋漂亮的新房子，邀请她来住时一定会大吃一惊。', summaryEn:'The writer told his sister in Nigeria that they are living in a beautiful new house in the country, and she will get a surprise when she visits.' },
  { id:24, title:'It could be worse', titleCn:'不幸中之万幸', text:['I entered the hotel manager\'s office and sat down.','I had just lost $50 and I felt very upset.','"I left the money in my room," I said, "and it\'s not there now."','The manager was sympathetic, but he could do nothing.','"Everyone\'s losing money these days," he said.','He started to complain about this wicked world but was interrupted by a knock at the door.'], vocab:[['manager','/ˈmænɪdʒə/','经理'],['upset','/ʌpˈset/','不安的'],['sympathetic','/ˌsɪmpəˈθetɪk/','表示同情的'],['complain','/kəmˈpleɪn/','抱怨'],['wicked','/ˈwɪkɪd/','邪恶的'],['interrupt','/ˌɪntəˈrʌpt/','打断']], notes:['could do nothing 什么也做不了。','complain about 抱怨。','be interrupted by 被……打断。'], tags:['一般过去时','被动语态'], difficulty:2, summary:'作者丢了50美元去找旅馆经理，经理表示同情但无能为力，正要抱怨世道时被敲门声打断。', summaryEn:'The writer lost $50 and went to the hotel manager. The manager was sympathetic but could do nothing, and was interrupted by a knock while complaining.' },
  { id:25, title:'Do the English speak English?', titleCn:'英国人讲的是英语吗？', text:['I arrived in London at last. The railway station was big, black and dark.','I did not know the way to my hotel, so I asked a porter.','I not only spoke English very carefully, but very clearly as well.','The porter, however, could not understand me.','I repeated my question several times and at last he understood.','He answered me, but he spoke neither slowly nor clearly.'], vocab:[['railway','/ˈreɪlweɪ/','铁路'],['porter','/ˈpɔːtə/','搬运工'],['clearly','/ˈklɪəli/','清楚地'],['neither','/ˈnaɪðə/','既不'],['nor','/nɔː/','也不'],['several','/ˈsevrəl/','几个']], notes:['not only...but also 不仅……而且。','neither...nor 既不……也不。','at last 最终。'], tags:['并列连词','否定结构'], difficulty:3, summary:'作者到达伦敦后问路，发现自己说的英语搬运工听不懂，而搬运工的回答他也听不清，引发了"英国人讲英语吗"的疑问。', summaryEn:'Arriving in London, the writer asked a porter for directions. Despite speaking carefully, the porter could not understand, and the porter spoke neither slowly nor clearly.' },
  { id:26, title:'The best art critics', titleCn:'最佳艺术评论家', text:['I am an art student and I paint a lot of pictures.','Many people pretend that they understand modern art.','They always tell you what a picture is about.','Of course, they are completely wrong about it.','My young sister is only seven, but she always tells me whether my pictures are good or not.','I showed one of my paintings to a famous art critic and he said it was the worst painting he had ever seen.'], vocab:[['critic','/ˈkrɪtɪk/','评论家'],['pretend','/prɪˈtend/','假装'],['completely','/kəmˈpliːtli/','完全地'],['whether','/ˈweðə/','是否'],['painting','/ˈpeɪntɪŋ/','画作'],['famous','/ˈfeɪməs/','著名的']], notes:['pretend that... 假装……。','whether...or not 是否。','the worst...he had ever seen 过去完成时表示"曾经"。'], tags:['宾语从句','现在完成时'], difficulty:3, summary:'作者是学艺术的学生，发现很多人假装懂现代艺术，而他七岁的妹妹倒能诚实地评价他的画。', summaryEn:'An art student finds that many people pretend to understand modern art, but his seven-year-old sister always tells him honestly whether his paintings are good.' },
  { id:27, title:'A wet night', titleCn:'雨夜', text:['Late in the afternoon, the boys put up their tent in the middle of a field.','As soon as this was done, they cooked a meal over an open fire.','They were all hungry and the food smelled good.','After a wonderful meal, they told stories and sang songs by the campfire.','But some time later it began to rain.','The boys felt tired so they put out the fire and crept into their tent.'], vocab:[['tent','/tent/','帐篷'],['field','/fiːld/','田野'],['campfire','/ˈkæmpfaɪə/','篝火'],['crept','/krept/','爬行'],['wonderful','/ˈwʌndəfl/','精彩的'],['hungry','/ˈhʌŋɡri/','饥饿的']], notes:['put up their tent 搭起帐篷。','as soon as 一……就。','put out the fire 扑灭篝火。'], tags:['一般过去时','时间状语从句'], difficulty:2, summary:'几个男孩在田野搭帐篷野营，享受了美妙的晚餐和篝火晚会，但后来下雨了，他们只好熄灭篝火钻进帐篷。', summaryEn:'Boys set up their tent in a field, had a wonderful meal by the campfire, told stories and sang songs, but later it began to rain and they crept into their tent.' },
  { id:28, title:'No parking', titleCn:'禁止停车', text:['Jasper White is one of those rare people who believes in ancient myths.','He has just bought a new house in the city, but ever since he moved in, he has had trouble with cars and their owners.','When he returns home at night, he always finds that someone has parked a car outside his gate.','Because of this, he has not been able to get his own car into his garage even once.','Jasper has put up a "No Parking" sign outside his gate, but this has not had any effect.','Now he has put an ugly stone head over the gate and it has turned visitors to stone!'], vocab:[['myth','/mɪθ/','神话'],['garage','/ˈɡærɑːʒ/','车库'],['effect','/ɪˈfekt/','效果'],['ugly','/ˈʌɡli/','丑陋的'],['ancient','/ˈeɪnʃənt/','古代的'],['owner','/ˈəʊnə/','主人']], notes:['ever since 自从。','because of this 因此。','turn...to stone 把……变成石头。'], tags:['现在完成时','定语从句'], difficulty:3, summary:'贾斯珀受停车问题困扰，在门口放了禁止停车牌不管用，于是放了一个丑陋的石头像，结果把来访者都"变成了石头"。', summaryEn:'Jasper White has trouble with people parking outside his gate. His "No Parking" sign had no effect, so he put up an ugly stone head that has shocked visitors.' },
  { id:29, title:'Taxi!', titleCn:'出租汽车！', text:['Captain Ben Fawcett has bought an unusual taxi and has begun a new service.','The "taxi" is a small Swiss aeroplane called a "Pilatus Porter".','This wonderful plane can carry seven passengers.','The most surprising thing about it, however, is that it can land anywhere.','Captain Fawcett\'s first passenger was a doctor who flew from Birmingham to a lonely village in the Welsh mountains.','Since then, Captain Fawcett has flown passengers to many unusual places.'], vocab:[['taxi','/ˈtæksi/','出租汽车'],['passenger','/ˈpæsɪndʒə/','乘客'],['Swiss','/swɪs/','瑞士的'],['service','/ˈsɜːvɪs/','服务'],['lonely','/ˈləʊnli/','偏僻的'],['mountain','/ˈmaʊntɪn/','山']], notes:['called a "Pilatus Porter" 过去分词作后置定语。','the most surprising thing 最令人惊讶的事。','since then 自从那时起。'], tags:['定语从句','现在完成时'], difficulty:3, summary:'福西特上尉买了一架小型瑞士飞机当出租车，可以在任何地方降落，已经载客到过许多不同寻常的地方。', summaryEn:'Captain Fawcett bought a small Swiss plane as a taxi. It can carry seven passengers and land anywhere, and has flown to many unusual places.' },
  { id:30, title:'Football or polo?', titleCn:'足球还是水球？', text:['The Wayle is a small river that cuts across the park near my home.','I like sitting by the Wayle on fine afternoons.','It was warm last Sunday, so I went and sat on the river bank as usual.','Some children were playing games on the bank and there were some people rowing on the river.','Suddenly, one of the children kicked a ball very hard and it went towards a passing boat.','Some people on the river bank called out to the man in the boat, but he did not hear them.'], vocab:[['polo','/ˈpəʊləʊ/','水球'],['river','/ˈrɪvə/','河'],['bank','/bæŋk/','岸'],['rowing','/ˈrəʊɪŋ/','划船'],['towards','/təˈwɔːdz/','朝'],['suddenly','/ˈsʌdnli/','突然']], notes:['cut across 穿过。','as usual 像往常一样。','call out to 向……喊叫。'], tags:['过去进行时','定语从句'], difficulty:2, summary:'作者坐在河边看孩子们踢球，一个孩子用力把球踢向一艘路过的船上的人，岸上的人朝船上的人喊叫但他没听见。', summaryEn:'While sitting by the river, the writer watched children playing. One child kicked a ball hard towards a passing boat, but the man in the boat did not hear people shouting.' },
  { id:31, title:'Success story', titleCn:'成功的故事', text:['Yesterday afternoon Frank Hawkins was telling me about his experiences as a young man.','Before he retired, Frank was the head of a very large business company.','"I must have been very hard-working," he said with a smile.','He then told me that as a boy he used to work in a small shop.','It was his job to repair bicycles and at that time he used to work fourteen hours a day.','He saved money for years and in 1958 he bought a small workshop of his own.'], vocab:[['retire','/rɪˈtaɪə/','退休'],['company','/ˈkʌmpəni/','公司'],['hard-working','/ˌhɑːd ˈwɜːkɪŋ/','勤奋的'],['workshop','/ˈwɜːkʃɒp/','车间'],['experience','/ɪkˈspɪəriəns/','经历'],['repair','/rɪˈpeə/','修理']], notes:['used to do 过去常常做某事。','of his own 属于他自己的。','It was his job to... 做……是他的工作。'], tags:['过去时态','used to'], difficulty:3, summary:'弗兰克·霍金斯退休前是一家大公司的老板，他年轻时在小店里修自行车，经过多年攒钱终于开了自己的小作坊。', summaryEn:'Frank Hawkins, who retired as head of a large company, used to work in a small shop repairing bicycles as a boy. He saved money for years and bought his own workshop.' },
  { id:32, title:'Shopping made easy', titleCn:'购物变得很方便', text:['People are not so honest as they once were.','The temptation to steal is greater than ever before, especially in large shops.','A detective recently watched a well-dressed woman who always went into a large store on Monday mornings.','One Monday, there were fewer people in the shop than usual when the woman came in.','So it was easier for the detective to watch her.','The woman first bought a few small articles. After a little time, she chose one of the most expensive dresses in the shop and handed it to an assistant.'], vocab:[['honest','/ˈɒnɪst/','诚实的'],['temptation','/tempˈteɪʃn/','诱惑'],['detective','/dɪˈtektɪv/','侦探'],['article','/ˈɑːtɪkl/','物品'],['expensive','/ɪkˈspensɪv/','昂贵的'],['assistant','/əˈsɪstənt/','售货员']], notes:['not so...as 不如……那样。','fewer than usual 比平常少。','hand...to 把……递给。'], tags:['比较级','定语从句'], difficulty:3, summary:'一个侦探注意到一位穿着讲究的女士总在周一上午去大商店，他观察她偷窃昂贵衣服的全过程。', summaryEn:'A detective watched a well-dressed woman who always visited a large shop on Mondays. He observed her shoplifting expensive dresses.' },
  { id:33, title:'Out of the darkness', titleCn:'冲出黑暗', text:['Nearly a week passed before the girl was able to explain what had happened to her.','She had set out from the coast early in the morning and had swum towards the English coast.','She had been swimming for six hours when she saw a light ahead of her.','The light came from a small boat. A man in the boat saw her and helped her in.','She had been in the sea for six hours because she had been caught in a storm.','When she arrived at the shore, she was too tired to go any further.'], vocab:[['darkness','/ˈdɑːknəs/','黑暗'],['coast','/kəʊst/','海岸'],['ahead','/əˈhed/','前方'],['shore','/ʃɔː/','岸边'],['storm','/stɔːm/','暴风雨'],['further','/ˈfɜːðə/','更远地']], notes:['set out from 从……出发。','be caught in 遭遇。','too...to... 太……而不能……。'], tags:['过去完成时','过去进行时'], difficulty:3, summary:'一个女孩从海岸出发游向英国海岸，途中遭遇暴风雨，游了六小时后被小船上的人救起，花了将近一周才能讲述这段经历。', summaryEn:'A girl swam from the coast towards England but was caught in a storm. After six hours she was rescued by a man in a small boat and was too tired to continue.' },
  { id:34, title:'Quick work', titleCn:'破案神速', text:['Dan Robinson has been worried all week.','Last Tuesday he received a letter from the local police.','In the letter he was asked to call at the station.','Dan wondered why he was wanted by the police, but he went to the station yesterday.','At the station, he was told by a smiling policeman that his bicycle had been found.','The bicycle was picked up in a small village four hundred miles away. It is now being sent to his home by train.'], vocab:[['police','/pəˈliːs/','警察'],['station','/ˈsteɪʃn/','局，站'],['wonder','/ˈwʌndə/','想知道'],['village','/ˈvɪlɪdʒ/','村庄'],['mile','/maɪl/','英里'],['smiling','/ˈsmaɪlɪŋ/','微笑的']], notes:['be asked to 被要求。','call at the station 到警察局去一趟。','pick up 捡到，找到。'], tags:['被动语态','间接引语'], difficulty:3, summary:'丹收到警察局的信，忐忑不安地去了才知道他丢失的自行车在四百英里外被找到了，正在用火车运回。', summaryEn:'Dan was worried after receiving a letter from the police. At the station he was told his bicycle had been found four hundred miles away and was being sent home by train.' },
  { id:35, title:'Stop thief!', titleCn:'捉贼！', text:['Roy Trenton used to drive a taxi. A short while ago, however, he became a bus driver and he has not regretted it.','He is finding his new work far more exciting.','When he was driving along Catford Street recently, he saw two thieves rush out of a shop and run towards a waiting car.','One of them was carrying a bag full of money.','Roy acted quickly and drove the bus straight at the thieves.','The one with the money got such a fright that he dropped the bag.'], vocab:[['thief','/θiːf/','小偷'],['regret','/rɪˈɡret/','后悔'],['exciting','/ɪkˈsaɪtɪŋ/','令人兴奋的'],['fright','/fraɪt/','惊吓'],['drop','/drɒp/','掉落'],['straight','/streɪt/','径直地']], notes:['used to do 过去常常做某事。','far more exciting 令人兴奋得多。','such...that 如此……以至于。'], tags:['such...that','结果状语从句'], difficulty:3, summary:'罗伊从出租车司机改行当公交车司机，一次他看到两个小偷从商店跑出，便开车直冲过去，小偷吓得丢掉了钱袋。', summaryEn:'Roy, a former taxi driver turned bus driver, saw two thieves rushing from a shop. He drove the bus straight at them, and one thief dropped the bag of money in fright.' },
  { id:36, title:'Across the Channel', titleCn:'横渡英吉利海峡', text:['Debbie Hart is going to swim across the English Channel tomorrow.','She is going to set out from the French coast at five o\'clock in the morning.','Debbie is only eleven years old and she hopes to set up a new world record.','She is a strong swimmer and many people feel that she is sure to succeed.','Debbie\'s father will set out with her in a small boat.','Mr. Hart has trained his daughter for years. Tomorrow he will be watching her anxiously as she swims the long distance to England.'], vocab:[['Channel','/ˈtʃænl/','海峡'],['record','/ˈrekɔːd/','纪录'],['coast','/kəʊst/','海岸'],['anxiously','/ˈæŋkʃəsli/','焦急地'],['distance','/ˈdɪstəns/','距离'],['train','/treɪn/','训练']], notes:['be going to 打算做某事。','set up a new world record 创造新的世界纪录。','be sure to 一定会。'], tags:['将来时态','宾语从句'], difficulty:3, summary:'11岁的黛比·哈特准备横渡英吉利海峡，她的父亲多年来一直训练她，将乘小船与她同行，焦急地注视她游完全程。', summaryEn:'Eleven-year-old Debbie Hart plans to swim across the English Channel. Her father, who has trained her for years, will accompany her in a small boat.' },
  { id:37, title:'The Olympic Games', titleCn:'奥林匹克运动会', text:['The Olympic Games will be held in our country in four years\' time.','As a great many people will be visiting the country, the government will be building new hotels, an immense stadium, and a new Olympic-standard swimming pool.','The Games will be held just outside the capital and the whole area will be called "Olympic City".','Workers will have completed the new roads by the end of this year.','Everybody will be watching anxiously as the new buildings go up.','We are all very excited and are looking forward to the Olympic Games.'], vocab:[['Olympic','/əˈlɪmpɪk/','奥林匹克的'],['government','/ˈɡʌvənmənt/','政府'],['immense','/ɪˈmens/','巨大的'],['stadium','/ˈsteɪdiəm/','体育场'],['capital','/ˈkæpɪtl/','首都'],['anxiously','/ˈæŋkʃəsli/','急切地']], notes:['in four years\' time 四年之后。','a great many 许多。','look forward to 期待。'], tags:['将来进行时','将来完成时'], difficulty:4, summary:'奥运会四年后将在本国举行，政府正在建设新旅馆、体育场和游泳池，所有人都满怀期待。', summaryEn:'The Olympic Games will be held in four years. The government is building new hotels, a stadium, and a swimming pool. Everyone is looking forward to the Games.' },
  { id:38, title:'Everything except the weather', titleCn:'唯独没有考虑天气', text:['My old friend, Harrison, had lived in the Mediterranean for many years before he returned to England.','He had often dreamed of retiring in England and had planned to settle down in the country.','He had no sooner returned than he bought a fine house and went to live there.','Almost immediately he began to complain about the weather, for even though it was still summer, it rained continually.','In the end, it was more than he could bear.','He had hardly had time to settle down when he sold the house and left the country.'], vocab:[['except','/ɪkˈsept/','除了'],['Mediterranean','/ˌmedɪtəˈreɪniən/','地中海'],['retire','/rɪˈtaɪə/','退休'],['continually','/kənˈtɪnjuəli/','不断地'],['complain','/kəmˈpleɪn/','抱怨'],['bear','/beə/','忍受']], notes:['no sooner...than 一……就。','even though 即使。','more than he could bear 超出他的承受能力。'], tags:['no sooner...than','让步状语从句'], difficulty:4, summary:'哈里森在地中海住了多年后回到英国养老，刚买好房子就开始抱怨天气，最后不堪忍受又卖房离开了。', summaryEn:'Harrison returned to England to retire after years in the Mediterranean. He bought a house but immediately complained about the rain and soon sold it and left.' },
  { id:39, title:'Am I all right?', titleCn:'我是否痊愈？', text:['While John Gilbert was in hospital, he asked his doctor to tell him whether his operation had been successful.','The doctor refused to do so the following day.','Instead, the patient asked for a bedside telephone.','When he was alone, he telephoned the hospital exchange and asked for Doctor Millington.','When the doctor answered the phone, Mr. Gilbert said he was inquiring about a certain patient, a Mr. John Gilbert.','He asked if Mr. Gilbert\'s operation had been successful and the doctor told him that it had been.'], vocab:[['hospital','/ˈhɒspɪtl/','医院'],['operation','/ˌɒpəˈreɪʃn/','手术'],['successful','/səkˈsesfl/','成功的'],['patient','/ˈpeɪʃnt/','病人'],['refuse','/rɪˈfjuːz/','拒绝'],['inquire','/ɪnˈkwaɪə/','询问']], notes:['ask sb. to do sth. 请求某人做某事。','ask for 要求。','answer the phone 接电话。'], tags:['间接引语','宾语从句'], difficulty:3, summary:'约翰·吉尔伯特住院做手术后，医生拒绝告诉他结果，于是他自己打电话到医院以第三方身份询问手术是否成功。', summaryEn:'John Gilbert asked his doctor about his operation but was refused. He then called the hospital himself, pretending to be inquiring about a patient named Mr. John Gilbert.' },
  { id:40, title:'Food and talk', titleCn:'进餐与交谈', text:['Last week at a dinner party, the hostess asked me to sit next to Mrs. Rumbold.','Mrs. Rumbold was a large, unsmiling lady in a tight black dress.','She did not even look up when I took my seat beside her.','Her eyes were fixed on her plate and in a short time, she was busy eating.','I tried to make conversation. "A new play is coming to \'The Globe\' soon," I said. "Will you be seeing it?"','"No," she answered. "Will you be eating your food or talking?"'], vocab:[['hostess','/ˈhəʊstəs/','女主人'],['conversation','/ˌkɒnvəˈseɪʃn/','交谈'],['unsmiling','/ʌnˈsmaɪlɪŋ/','不笑的'],['plate','/pleɪt/','盘子'],['tight','/taɪt/','紧身的'],['beside','/bɪˈsaɪd/','在……旁边']], notes:['be fixed on 盯着。','be busy doing 忙于做某事。','a new play is coming to 将上演。'], tags:['过去进行时','将来时态'], difficulty:3, summary:'作者在晚宴上被安排坐在冷面女士朗博尔德夫人旁边，试图搭话却只得到一句冷冰冰的反问。', summaryEn:'At a dinner party, the writer was seated next to Mrs. Rumbold, who was busy eating and uninterested in conversation. When asked about a play, she replied sharply.' },
  { id:41, title:'Do you call that a hat?', titleCn:'你把那叫帽子吗？', text:['"Do you call that a hat?" I said to my wife."You needn\'t be so rude about it," my wife answered as she looked at herself in the mirror.','I sat down on one of those modern chairs with holes in it and waited.','We had been in the hat shop for half an hour and my wife was still in front of the mirror.','"We mustn\'t buy things we don\'t need," I remarked suddenly.','I regretted the words as soon as I had said them.','"You needn\'t have said that," my wife answered. "I needn\'t remind you of that terrible tie you bought yesterday."'], vocab:[['hat','/hæt/','帽子'],['rude','/ruːd/','粗鲁的'],['mirror','/ˈmɪrə/','镜子'],['remark','/rɪˈmɑːk/','说道'],['terrible','/ˈterəbl/','糟糕的'],['remind','/rɪˈmaɪnd/','提醒']], notes:['needn\'t be 不必。','look at herself 照镜子。','remind sb. of sth. 提醒某人某事。'], tags:['情态动词','虚拟语气'], difficulty:3, summary:'作者陪妻子买帽子，忍不住说了一句不需要买不需要的东西，结果被妻子用他昨天买的糟糕领带反唇相讥。', summaryEn:'The writer accompanied his wife to a hat shop. He remarked they mustn\'t buy unnecessary things, but his wife reminded him of the terrible tie he had bought.' },
  { id:42, title:'Not very musical', titleCn:'不太懂音律', text:['As we had had a long walk through one of the markets of old Delhi, we stopped at a square to have a rest.','After a time, we noticed a snake charmer with two large baskets at the other side of the square.','As soon as he saw us, he picked up a long pipe which was covered with coins and opened one of the baskets.','When he began to play a tune, we had our first glimpse of the snake.','It rose out of the basket and began to follow the movements of the pipe.','We were very much surprised when the snake charmer suddenly began to play jazz and modern pop songs.'], vocab:[['musical','/ˈmjuːzɪkl/','懂音乐的'],['charmer','/ˈtʃɑːmə/','耍蛇人'],['pipe','/paɪp/','管乐器'],['glimpse','/ɡlɪmps/','一瞥'],['tune','/tjuːn/','曲子'],['movement','/ˈmuːvmənt/','移动']], notes:['have a glimpse of 瞥见。','be covered with 被……覆盖。','follow the movements of 跟随……的动作。'], tags:['过去完成时','时间状语从句'], difficulty:3, summary:'在德里市场休息时，作者看到耍蛇人吹管乐器让蛇起舞，但当耍蛇人突然吹起爵士乐时蛇却毫无反应。', summaryEn:'Watching a snake charmer in Delhi, the writer saw a snake rise from a basket and follow the pipe\'s movements, but when jazz was played the snake was not musical at all.' },
  { id:43, title:'Over the South Pole', titleCn:'飞越南极', text:['In 1929, three years after his flight over the North Pole, the American explorer, R.E. Byrd, successfully flew over the South Pole for the first time.','Though, at first, Byrd and his men were able to take a great many photographs of the mountains that lay below, they soon ran into serious trouble.','At one point, it seemed certain that their plane would crash.','It could only get over the mountains if it rose to 10,000 feet.','Byrd at once ordered his men to throw out two heavy food sacks.','The plane was then able to rise and it cleared the mountains by 200 feet.'], vocab:[['pole','/pəʊl/','极'],['explorer','/ɪkˈsplɔːrə/','探险家'],['photograph','/ˈfəʊtəɡrɑːf/','照片'],['crash','/kræʃ/','坠毁'],['mountain','/ˈmaʊntɪn/','山'],['sack','/sæk/','袋']], notes:['for the first time 第一次。','run into serious trouble 遇到严重困难。','it seemed certain that 似乎确定……。'], tags:['虚拟语气','条件状语从句'], difficulty:4, summary:'美国探险家伯德在1929年首次飞越南极，途中飞机险些坠毁，扔掉两袋食物后才飞越了山脉。', summaryEn:'American explorer R.E. Byrd flew over the South Pole in 1929. His plane nearly crashed into mountains, but after throwing out food sacks, it cleared the mountains by 200 feet.' },
  { id:44, title:'Through the forest', titleCn:'穿越森林', text:['Mrs. Anne Sterling did not think of the risk she was taking when she ran through a forest after two men.','They had rushed up to her while she was having a picnic at the edge of a forest with her children and tried to steal her handbag.','In the struggle, the strap broke and, with the bag in their possession, both men started running through the trees.','Mrs. Sterling got so angry that she ran after them.','She was soon out of breath, but she continued to run.','When she caught up with them, she saw that they had sat down and were going through the contents of the bag.'], vocab:[['risk','/rɪsk/','风险'],['forest','/ˈfɒrɪst/','森林'],['strap','/stræp/','带子'],['possession','/pəˈzeʃn/','拥有'],['contents','/ˈkɒntents/','里面的东西'],['breathe','/briːð/','呼吸']], notes:['rush up to 冲向。','out of breath 上气不接下气。','go through 翻看。'], tags:['过去完成时','结果状语从句'], difficulty:3, summary:'斯特林夫人在森林野餐时遇到抢劫，她在树丛中追赶两个抢包的男子，最终追上时发现他们正在翻包里的东西。', summaryEn:'Mrs. Sterling chased two men through a forest after they stole her handbag during a picnic. She caught up with them as they were going through the bag\'s contents.' },
  { id:45, title:'A clear conscience', titleCn:'问心无愧', text:['The whole village soon learnt that a large sum of money had been lost.','Sam Benton, the local butcher, had lost his wallet while taking his savings to the post office.','Sam was sure that the wallet must have been found by one of the villagers, but it was not returned to him.','Three months passed, and then one morning, Sam found his wallet outside his front door.','It had been wrapped up in newspaper and it contained half the money he had lost.','Together with the wallet, there was a note which said: "A thief, yes, but only 50 per cent a thief!"'], vocab:[['conscience','/ˈkɒnʃəns/','良心'],['butcher','/ˈbʊtʃə/','屠夫'],['wallet','/ˈwɒlɪt/','钱包'],['savings','/ˈseɪvɪŋz/','积蓄'],['wrap','/ræp/','包裹'],['contain','/kənˈteɪn/','包含']], notes:['must have been found 表示对过去的推测。','wrap up 包起来。','together with 和……一起。'], tags:['过去完成时','被动语态'], difficulty:3, summary:'屠夫萨姆丢了钱包，三个月后钱包被送回一半的钱，附言说"是小偷，但只偷了一半"。', summaryEn:'Sam the butcher lost his wallet with his savings. Three months later, half the money was returned with a note saying "A thief, yes, but only 50 per cent a thief!"' },
  { id:46, title:'Expensive and uncomfortable', titleCn:'既昂贵又受罪', text:['When a plane from London arrived at Sydney airport, workers began to unload a number of wooden boxes.','They contained clothing and one of the boxes was extremely heavy.','A worker noticed the address on one of the boxes and reported it to the manager.','The manager had the box opened and found a man inside.','He had been in the box from London to Sydney and had survived the journey.','He was arrested and ordered to pay $3,500 for the cost of the trip.'], vocab:[['unload','/ʌnˈləʊd/','卸货'],['wooden','/ˈwʊdn/','木制的'],['clothing','/ˈkləʊðɪŋ/','衣服'],['extremely','/ɪkˈstriːmli/','极其'],['survive','/səˈvaɪv/','存活'],['arrest','/əˈrest/','逮捕']], notes:['a number of 许多。','have the box opened 让人打开箱子。','be ordered to 被命令。'], tags:['被动语态','过去完成时'], difficulty:4, summary:'一架从伦敦飞来的飞机卸货时发现一个极重的木箱，里面竟然藏着一个人，他从伦敦一路藏到悉尼，最后被捕并被罚支付旅费。', summaryEn:'Workers unloading a plane at Sydney found a man hiding inside a wooden box. He had survived the journey from London and was arrested and fined $3,500.' },
  { id:47, title:'A thirsty ghost', titleCn:'嗜酒的鬼魂', text:['A public house which has recently been bought by Mr. Ian Thompson is up for sale.','Mr. Thompson is going to sell it because it is haunted.','He told me that he could not go to sleep at night because he heard strange noises.','A ghost must have been drinking whisky, for in the morning the bottles were found empty.','Mr. Thompson said he had turned off all the lights before he went to bed.','He even offered the ghost some money to go away, but the ghost refused.'], vocab:[['ghost','/ɡəʊst/','鬼魂'],['haunted','/ˈhɔːntɪd/','闹鬼的'],['whisky','/ˈwɪski/','威士忌'],['strange','/streɪndʒ/','奇怪的'],['empty','/ˈempti/','空的'],['refuse','/rɪˈfjuːz/','拒绝']], notes:['be up for sale 待售。','must have been drinking 对过去的推测。','turn off 关闭。'], tags:['情态动词','间接引语'], difficulty:3, summary:'汤普森先生的酒吧闹鬼，每晚听到怪声，威士忌瓶总是空的，他出钱让鬼走开但鬼拒绝了。', summaryEn:'Mr. Thompson\'s pub is haunted. He hears strange noises at night and finds whisky bottles empty in the morning. He offered the ghost money to leave but it refused.' },
  { id:48, title:'Did you want to tell me something?', titleCn:'你想对我说什么吗？', text:['Dentists always ask questions when it is impossible for you to answer.','My dentist had just pulled out one of my teeth and had told me to rest for a while.','I tried to say something, but my mouth was full of cotton wool.','He knew I collected birds\' eggs and asked me whether my collection was growing.','He then asked me how my brother was and whether I liked my new job in London.','In answer to these questions I either nodded or made strange noises.'], vocab:[['dentist','/ˈdentɪst/','牙医'],['impossible','/ɪmˈpɒsəbl/','不可能的'],['cotton','/ˈkɒtn/','棉花'],['collection','/kəˈlekʃn/','收藏'],['nod','/nɒd/','点头'],['strange','/streɪndʒ/','奇怪的']], notes:['it is impossible for you to answer 对你来说不可能回答。','full of 充满。','in answer to 作为对……的回答。'], tags:['间接引语','形式主语'], difficulty:3, summary:'作者在看牙医时，医生在拔牙后不停提问，而他嘴里塞满棉花无法说话，只能点头或发出奇怪的声音。', summaryEn:'At the dentist, the writer could not answer questions because his mouth was full of cotton wool. He could only nod or make strange noises in response.' },
  { id:49, title:'The end of a dream', titleCn:'美梦告终', text:['Tired of sleeping on the floor, a young man in Teheran saved up for years to buy a real bed.','For the first time in his life, he became the proud owner of a bed which had springs and a mattress.','Because the weather was very hot, he carried the bed on to the flat roof of his house.','He slept very well for the first two nights, but on the third night, a storm blew up.','A gust of wind swept the bed off the roof and sent it crashing into the courtyard below.','The young man did not wake up until the bed had struck the ground.'], vocab:[['mattress','/ˈmætrəs/','床垫'],['spring','/sprɪŋ/','弹簧'],['roof','/ruːf/','屋顶'],['courtyard','/ˈkɔːtjɑːd/','院子'],['gust','/ɡʌst/','一阵'],['crash','/kræʃ/','碰撞']], notes:['tired of 厌倦了。','save up for years 攒了多年钱。','not...until 直到……才。'], tags:['过去完成时','结果状语从句'], difficulty:3, summary:'一个德黑兰年轻人攒钱买了张床放在屋顶睡觉，第三天夜里大风把床吹到院子里，他直到床落地才醒。', summaryEn:'A young man in Teheran saved up to buy a real bed and slept on the roof. A storm swept the bed off the roof, but he did not wake until it crashed into the courtyard.' },
  { id:50, title:'Taken for a ride', titleCn:'乘车兜风', text:['I love travelling in the country, but I don\'t like losing my way.','I went on an excursion recently, but my trip took me longer than I expected.','"I\'m going to Woodford Green," I said to the conductor as I got on the bus, "but I don\'t know where it is."','"I\'ll tell you where to get off," answered the conductor.','I sat in the front of the bus to get a good view of the countryside.','After some time, the bus stopped. Looking round, I realized that I was the only passenger left on the bus.'], vocab:[['excursion','/ɪkˈskɜːʃn/','远足'],['conductor','/kənˈdʌktə/','售票员'],['view','/vjuː/','景色'],['countryside','/ˈkʌntrisaɪd/','乡间'],['passenger','/ˈpæsɪndʒə/','乘客'],['realize','/ˈrɪəlaɪz/','意识到']], notes:['lose one\'s way 迷路。','take me longer than expected 比预期花的时间长。','get off 下车。'], tags:['宾语从句','现在分词'], difficulty:3, summary:'作者去远足乘公交车，让售票员提醒他在哪下车，结果坐过头成了车上唯一的乘客。', summaryEn:'The writer took a bus excursion but missed his stop. After some time he realized he was the only passenger left on the bus.' },
  { id:51, title:'Reward for virtue', titleCn:'对美德的奖赏', text:['My friend, Herbert, has always been fat, but things got so bad recently that he decided to go on a diet.','He began his diet a week ago. First of all, he wrote out a long list of all the foods which were forbidden.','The list included most of the things Herbert loves: butter, potatoes, rice, beer, milk, chocolate, and sweets.','Yesterday I paid him a visit. I rang the bell and was not surprised to see that Herbert was still as fat as ever.','He led me into his room and hurriedly hid a large parcel under his desk.','It was obvious that he was very embarrassed.'], vocab:[['virtue','/ˈvɜːtʃuː/','美德'],['diet','/ˈdaɪət/','节食'],['forbidden','/fəˈbɪdn/','禁止的'],['include','/ɪnˈkluːd/','包括'],['obvious','/ˈɒbviəs/','明显的'],['embarrassed','/ɪmˈbærəst/','尴尬的']], notes:['go on a diet 节食。','first of all 首先。','as fat as ever 和以前一样胖。'], tags:['比较级','定语从句'], difficulty:3, summary:'赫伯特决定节食减肥，列了一长串禁食清单，但一周后朋友来访时他还是和以前一样胖，还急忙把食物藏起来。', summaryEn:'Herbert went on a diet, listing all forbidden foods. A week later, a friend visited and found him still as fat as ever, hurriedly hiding a parcel under his desk.' },
  { id:52, title:'A pretty carpet', titleCn:'漂亮的地毯', text:['We have just moved into a new house and I have been working hard all morning.','I have been trying to get my new room in order.','This has not been easy because I own over a thousand books.','To make matters worse, the room is rather small, so I have temporarily put my books on the floor.','At the moment, they cover every inch of floor space and I actually have to walk on them to get in or out of the room.','A short while ago, my sister helped me to carry one of my old bookcases up the stairs.'], vocab:[['carpet','/ˈkɑːpɪt/','地毯'],['temporarily','/ˈtemprərəli/','暂时地'],['actually','/ˈæktʃuəli/','实际上'],['bookcase','/ˈbʊkkeɪs/','书架'],['inch','/ɪntʃ/','英寸'],['space','/speɪs/','空间']], notes:['get...in order 把……整理好。','to make matters worse 更糟的是。','every inch 每一寸。'], tags:['现在完成进行时','比较级'], difficulty:3, summary:'作者搬进新房子后整理书籍，一千多本书铺满了地板，整个房间到处都是书，连进出都要踩着书走。', summaryEn:'The writer has been trying to organize a new room with over a thousand books. The books cover every inch of floor space and he has to walk on them.' },
  { id:53, title:'Hot snake', titleCn:'触电的蛇', text:['At last firemen have put out a big forest fire in California.','Since then, they have been trying to find out how the fire began.','Forest fires are often caused by broken glass or cigarette ends which people carelessly throw away.','Yesterday the firemen examined the ground carefully but were not able to find any broken glass.','They were also quite sure that a cigarette end did not start the fire.','This morning, however, a firemen accidentally discovered the cause. He noticed the remains of a snake which had been wound round the electric wires.'], vocab:[['fireman','/ˈfaɪəmən/','消防员'],['forest','/ˈfɒrɪst/','森林'],['examine','/ɪɡˈzæmɪn/','检查'],['accidentally','/ˌæksɪˈdentəli/','意外地'],['remains','/rɪˈmeɪnz/','残骸'],['wire','/ˈwaɪə/','电线']], notes:['put out 扑灭。','find out 查明。','be wound round 缠绕在。'], tags:['现在完成进行时','定语从句'], difficulty:4, summary:'加利福尼亚森林大火被扑灭后，消防员调查起火原因，最终发现是一条蛇缠在电线上触电引发了火灾。', summaryEn:'After putting out a forest fire in California, firemen discovered the cause was a snake that had been wound round electric wires and electrocuted.' },
  { id:54, title:'Sticky fingers', titleCn:'粘糊的手指', text:['After breakfast, I sent the children to school and then went to the shops.','It was still early when I returned home. The children were at school, my husband was at work and the house was quiet.','I decided to make some meat pies. In a short time I was busy mixing butter and flour and my hands were soon covered with sticky pastry.','At exactly that moment, the telephone rang. Nothing could have been more annoying.','I picked up the receiver between two sticky fingers and was dismayed when I recognized the voice of Mrs. Bates.','It took me ten minutes to persuade her to ring back later.'], vocab:[['sticky','/ˈstɪki/','粘的'],['flour','/ˈflaʊə/','面粉'],['pastry','/ˈpeɪstri/','面团'],['annoying','/əˈnɔɪɪŋ/','恼人的'],['receiver','/rɪˈsiːvə/','听筒'],['persuade','/pəˈsweɪd/','说服']], notes:['be covered with 被……覆盖。','nothing could have been 更不可能有比这更……的了。','persuade sb. to do 说服某人做某事。'], tags:['比较级','形式主语'], difficulty:3, summary:'作者做肉饼时双手沾满面团，这时电话响了，她用两根粘糊的手指拿起听筒，花了十分钟才说服对方稍后再打来。', summaryEn:'While making pastry with sticky fingers, the phone rang. The writer picked up the receiver with two sticky fingers and spent ten minutes persuading Mrs. Bates to call back later.' },
  { id:55, title:'Not a musical clock', titleCn:'并非音乐钟', text:['My grandfather used to work in a large clock factory.','After he retired, he brought a beautiful old clock home.','The clock had been made in 1800 and it still kept perfect time.','My grandfather was very proud of it. He cleaned it carefully every week.','One day, however, the clock began to play a tune every hour on the hour.','The tune was not very musical and it disturbed the whole neighborhood.'], vocab:[['clock','/klɒk/','钟'],['factory','/ˈfæktəri/','工厂'],['perfect','/ˈpɜːfɪkt/','准确的'],['proud','/praʊd/','自豪的'],['disturb','/dɪˈstɜːb/','打扰'],['neighborhood','/ˈneɪbəhʊd/','邻居们']], notes:['used to do 过去常常做某事。','be proud of 为……自豪。','every hour on the hour 每小时整点。'], tags:['used to','一般过去时'], difficulty:3, summary:'祖父退休后带回一座古老的大钟，走时精准，但有一天开始每小时整点奏出不悦耳的曲子，搅得邻居不安。', summaryEn:'The writer\'s grandfather brought home an old clock that kept perfect time. One day it began playing an unmusical tune every hour, disturbing the neighborhood.' },
  { id:56, title:'Faster than sound!', titleCn:'比声音还快！', text:['Once a year a race is held for old cars. A lot of cars entered for this race last year and there was a great deal of excitement just before it began.','One of the most handsome cars was a Rolls-Royce Silver Ghost.','The most unusual car was a Benz which had only three wheels.','Built in 1885, it was the oldest car taking part.','After a great many loud explosions, the race began.','Many of the cars broke down on the course and some drivers spent more time under their cars than in them!'], vocab:[['race','/reɪs/','比赛'],['wheel','/wiːl/','轮子'],['explosion','/ɪkˈspləʊʒn/','爆炸'],['handsome','/ˈhænsəm/','漂亮的'],['course','/kɔːs/','赛道'],['driver','/ˈdraɪvə/','驾驶员']], notes:['enter for 报名参加。','a great deal of 大量。','break down 抛锚。'], tags:['一般过去时','比较级'], difficulty:3, summary:'老式汽车年度比赛中，一辆只有三个轮子的1885年奔驰最引人注目，许多车在赛道上抛锚。', summaryEn:'An annual race for old cars included a handsome Rolls-Royce and an unusual three-wheeled Benz from 1885. Many cars broke down during the race.' },
  { id:57, title:'Can I help you, madam?', titleCn:'您要买什么，夫人？', text:['A woman in blue jeans stood at the window of an expensive shop.','Though she hesitated for a moment, she finally went in and asked to see a dress that was in the window.','The assistant who served her did not like the way she was dressed.','Glancing at her scornfully, he told her that the dress was sold.','The woman walked out of the shop angrily and decided to punish the assistant the next day.','She returned to the shop the following morning dressed in a fur coat, with a handbag in one hand and a long umbrella in the other.'], vocab:[['jeans','/dʒiːnz/','牛仔裤'],['hesitate','/ˈhezɪteɪt/','犹豫'],['scornfully','/ˈskɔːnfəli/','轻蔑地'],['punish','/ˈpʌnɪʃ/','惩罚'],['fur','/fɜː/','毛皮'],['umbrella','/ʌmˈbrelə/','雨伞']], notes:['ask to see 要求看。','glance at 瞥了一眼。','dressed in 穿着。'], tags:['过去分词','方式状语从句'], difficulty:3, summary:'一位穿牛仔裤的女士在高档服装店被店员轻视，第二天她穿着皮大衣回来准备报复。', summaryEn:'A woman in jeans was treated scornfully by a shop assistant. She returned the next day in a fur coat to punish the assistant.' },
  { id:58, title:'A blessing in disguise?', titleCn:'是因祸得福吗？', text:['The tiny village of Frinley is said to possess a "cursed tree".','Because the tree was mentioned in a newspaper, the number of visitors to Frinley has now increased.','The tree was planted near the church fifty years ago, but it is only in recent years that it has gained an evil reputation.','It is said that if anyone touches the tree, he will have bad luck.','If he picks a leaf from the tree, he will die.','The villagers have asked the local council to have the tree cut down, but so far the council has refused.'], vocab:[['blessing','/ˈblesɪŋ/','福'],['cursed','/ˈkɜːsɪd/','被诅咒的'],['reputation','/ˌrepjuˈteɪʃn/','名声'],['villager','/ˈvɪlɪdʒə/','村民'],['council','/ˈkaʊnsl/','委员会'],['evil','/ˈiːvl/','邪恶的']], notes:['be said to 据说。','it is only in recent years that 强调句型。','have...cut down 让人砍倒。'], tags:['虚拟语气','强调句型'], difficulty:4, summary:'弗林利村据说有一棵被诅咒的树，报纸报道后游客增多，村民要求砍树但委员会拒绝了。', summaryEn:'The village of Frinley is said to have a cursed tree. After a newspaper mentioned it, visitors increased. The villagers want it cut down but the council has refused.' },
  { id:59, title:'In or out?', titleCn:'进来还是出去？', text:['Our dog, Rex, used to sit outside our front gate and bark.','Every time he wanted to come into the garden he would bark until someone opened the gate.','As the neighbours complained of the noise, my husband spent weeks training him to press his paw on the latch to let himself in.','Rex soon became an expert at opening the gate.','However, when I was going out shopping last week, I noticed him in the garden near the gate.','This time he was barking so that someone would let him out!'], vocab:[['bark','/bɑːk/','吠叫'],['gate','/ɡeɪt/','大门'],['latch','/lætʃ/','门闩'],['paw','/pɔː/','爪子'],['complain','/kəmˈpleɪn/','抱怨'],['expert','/ˈekspɜːt/','能手']], notes:['every time 每次。','complain of 抱怨。','so that 以便。'], tags:['目的状语从句','used to'], difficulty:3, summary:'家犬雷克斯学会了自己开门进来，但后来它开始在花园里叫着要人开门让它出去。', summaryEn:'Rex the dog learned to open the gate by pressing the latch with his paw. Later, he began barking to be let out instead of in.' },
  { id:60, title:'The future', titleCn:'未来', text:['We often read in novels how a seemingly respectable person or family has some terrible secret which has been concealed from strangers for years.','The English language possesses a vivid saying to describe this sort of situation.','The terrible secret is called "a skeleton in the cupboard".','At some dramatic moment in the story, the dreadful secret becomes known and a reputation is ruined.','The reader\'s hair stands on end when he reads in the final pages of the novel that the heroine had hidden the body of her first husband under the kitchen floor.','Everyone has a skeleton in the cupboard, or so we are told.'], vocab:[['future','/ˈfjuːtʃə/','未来'],['seemingly','/ˈsiːmɪŋli/','表面上'],['conceal','/kənˈsiːl/','隐藏'],['skeleton','/ˈskelɪtn/','骷髅'],['dreadful','/ˈdredfl/','可怕的'],['reputation','/ˌrepjuˈteɪʃn/','名声']], notes:['conceal from 对……隐瞒。','hair stands on end 毛骨悚然。','or so we are told 据说是这样。'], tags:['定语从句','被动语态'], difficulty:4, summary:'英语中用"壁橱里的骷髅"来描述隐藏多年的丑闻，小说中常常在戏剧性的时刻揭露这些可怕的秘密。', summaryEn:'The English expression "a skeleton in the cupboard" describes a terrible secret. In novels, such secrets are often revealed at dramatic moments, ruining reputations.' },
  { id:61, title:'Trouble with the Hubble', titleCn:'哈勃望远镜的困难', text:['The Hubble telescope was launched into space by NASA on April 20, 1990 at a cost of over a billion dollars.','Right from the start there was trouble with the Hubble.','The pictures it sent us were very disappointing because its main mirror was faulty.','NASA is now going to put the telescope right, so it will soon be sending up four astronauts to repair it.','The shuttle Endeavour will be taking the astronauts to the Hubble.','A robot-arm from the Endeavour will grab the telescope and hold it while the astronauts make the necessary repairs.'], vocab:[['telescope','/ˈtelɪskəʊp/','望远镜'],['launch','/lɔːntʃ/','发射'],['mirror','/ˈmɪrə/','镜子'],['faulty','/ˈfɔːlti/','有缺陷的'],['astronaut','/ˈæstrənɔːt/','宇航员'],['shuttle','/ˈʃʌtl/','航天飞机']], notes:['at a cost of 花费。','right from the start 从一开始。','put...right 修复。'], tags:['将来进行时','被动语态'], difficulty:4, summary:'哈勃望远镜发射后发现主镜有缺陷，图片令人失望，NASA将派宇航员乘航天飞机去修理。', summaryEn:'The Hubble telescope was launched in 1990 but its main mirror was faulty. NASA planned to send astronauts on the shuttle Endeavour to repair it.' },
  { id:62, title:'After the fire', titleCn:'大火之后', text:['Firemen had been fighting the forest fire for nearly three weeks before they could get it under control.','A short time before, great trees had covered the countryside for miles around.','Now, smoke still rose up from the warm ground over the desolate hills.','Winter was coming on and the hills threatened the surrounding villages with destruction, for heavy rain would not only wash away the soil but would cause serious floods as well.','When the fire had at last been put out, the forest authorities ordered several tons of a special type of grass-seed which would grow quickly.','Seed was sprayed over the ground in huge quantities by aeroplanes.'], vocab:[['desolate','/ˈdesələt/','荒凉的'],['threaten','/ˈθretn/','威胁'],['destruction','/dɪˈstrʌkʃn/','毁灭'],['authority','/ɔːˈθɒrəti/','当局'],['spray','/spreɪ/','喷洒'],['quantity','/ˈkwɒntəti/','数量']], notes:['get under control 得到控制。','come on 来临。','in huge quantities 大量地。'], tags:['过去完成时','原因状语从句'], difficulty:4, summary:'森林大火扑灭后，光秃秃的山丘面临水土流失的威胁，当局用飞机大量喷洒草籽来防止进一步破坏。', summaryEn:'After a forest fire was put out, the bare hills threatened nearby villages with floods. Forest authorities sprayed grass-seed over the ground by aeroplane to prevent erosion.' },
  { id:63, title:'She was not amused', titleCn:'她并不觉得好笑', text:['Geoffrey Hampden has a large circle of friends and is very popular at parties.','Everybody admires him for his fine sense of humour. Everybody, that is, except his six-year-old daughter, Jenny.','Recently, one of Geoffrey\'s closest friends asked him to make a speech at a wedding reception.','Geoffrey agreed. He prepared the speech carefully and went to the wedding with Jenny.','He had included a large number of funny stories in the speech and, of course, it was a great success.','As soon as he had finished, Jenny told him she wanted to go home. She was not amused.'], vocab:[['admire','/ədˈmaɪə/','钦佩'],['humour','/ˈhjuːmə/','幽默'],['speech','/spiːtʃ/','演讲'],['wedding','/ˈwedɪŋ/','婚礼'],['reception','/rɪˈsepʃn/','招待会'],['amused','/əˈmjuːzd/','觉得好笑的']], notes:['a large circle of friends 朋友圈很大。','admire sb. for 因……钦佩某人。','that is 即，也就是说。'], tags:['一般过去时','过去完成时'], difficulty:3, summary:'杰弗里在婚礼上发表了一篇包含许多笑话的精彩演讲，大获成功，但六岁的女儿却说要回家，她并不觉得好笑。', summaryEn:'Geoffrey gave a funny speech at a wedding that was a great success, but his six-year-old daughter Jenny told him she wanted to go home because she was not amused.' },
  { id:64, title:'The Channel Tunnel', titleCn:'海峡隧道', text:['In 1858, a French engineer arrived in England with a plan for a twenty-one-mile tunnel under the English Channel.','He said that it would be possible to build a platform in the centre of the Channel.','Travellers could then take a train from England to the platform and then from the platform to France.','The plan was rejected because the British feared an invasion.','They did not want the French to be able to come to England easily.','In 1986, however, a new tunnel was actually begun. It was completed in 1994 and connects England and France.'], vocab:[['tunnel','/ˈtʌnl/','隧道'],['engineer','/ˌendʒɪˈnɪə/','工程师'],['platform','/ˈplætfɔːm/','平台'],['reject','/rɪˈdʒekt/','拒绝'],['invasion','/ɪnˈveɪʒn/','入侵'],['connect','/kəˈnekt/','连接']], notes:['a plan for 一个……的计划。','fear an invasion 担心入侵。','it would be possible to 有可能。'], tags:['被动语态','虚拟语气'], difficulty:4, summary:'1858年一位法国工程师提出建英吉利海峡隧道的计划被英国人否决，但1986年新隧道终于开工并于1994年完工。', summaryEn:'In 1858 a French engineer proposed a Channel tunnel, but the British rejected it fearing invasion. A new tunnel was finally begun in 1986 and completed in 1994.' },
  { id:65, title:'Jumbo versus the police', titleCn:'小象对警察', text:['Last Christmas, the circus owner, Jimmy Gates, decided to take some presents to a children\'s hospital.','Dressed up as Father Christmas and accompanied by a "guard of honour" of six pretty young girls, he set off down the main street of the city riding a baby elephant called Jumbo.','The police were not very pleased. However, as it was Christmas, they agreed to let him go.','Jumbo was walking quietly along the street when he suddenly turned left and walked into a shop.','It was clear that he was not going to leave until he had been given something.','A policeman walked alongside the elephant and Jimmy tried to get him away.'], vocab:[['circus','/ˈsɜːkəs/','马戏团'],['elephant','/ˈelɪfənt/','大象'],['Christmas','/ˈkrɪsməs/','圣诞节'],['alongside','/əˌlɒŋˈsaɪd/','在……旁边'],['accompany','/əˈkʌmpəni/','陪伴'],['guard','/ɡɑːd/','护卫']], notes:['dress up as 打扮成。','set off 出发。','agree to do 同意做某事。'], tags:['时间状语从句','过去分词'], difficulty:3, summary:'马戏团老板吉米骑着小象琼博去儿童医院送礼物，琼博中途走进一家商店不肯离开，警察也没办法。', summaryEn:'Jimmy Gates rode baby elephant Jumbo down the main street to deliver presents to a children\'s hospital. Jumbo entered a shop and refused to leave without a gift.' },
  { id:66, title:'Sweet as honey!', titleCn:'像蜜一样甜！', text:['In 1963 a Lancaster bomber crashed on Wallis Island, a remote place in the South Pacific, a long way west of Samoa.','The plane wasn\'t too badly damaged, but over the years, the crash was forgotten and the wreck remained undisturbed.','Then in 1989, twenty-six years later, the plane was accidentally rediscovered.','The American and Australian authorities organized an expedition to bring the wreck back to Australia.','By this time, a Lancaster bomber in reasonable condition was rare and worth rescuing.','The French authorities had the plane packaged and moved in parts back to France.'], vocab:[['bomber','/ˈbɒmə/','轰炸机'],['remote','/rɪˈməʊt/','偏远的'],['wreck','/rek/','残骸'],['undisturbed','/ˌʌndɪˈstɜːbd/','未被触动的'],['expedition','/ˌekspɪˈdɪʃn/','远征'],['rescue','/ˈreskjuː/','营救']], notes:['a long way west of 在……以西很远的地方。','worth rescuing 值得营救。','in parts 分部件。'], tags:['被动语态','过去完成时'], difficulty:4, summary:'一架兰开斯特轰炸机1963年坠落在偏远的沃利斯岛，26年后被重新发现，当局组织远征队将其运回修复。', summaryEn:'A Lancaster bomber crashed on a remote Pacific island in 1963. Rediscovered 26 years later, authorities organized an expedition to rescue the rare wreck.' },
  { id:67, title:'Volcanoes', titleCn:'火山', text:['Haroun Tazieff, the Polish scientist, has spent his lifetime studying active volcanoes and deep caves in all parts of the world.','In 1948, he went to Lake Kivu in the Congo to observe a new volcano which he later named Kituro.','Tazieff was able to set up his camp very close to the volcano while it was erupting violently.','Though he managed to take a number of brilliant photographs, he could not stay near the volcano for very long.','He noticed that a river of liquid rock was coming towards him.','It threatened to surround him completely, but Tazieff managed to escape just in time.'], vocab:[['volcano','/vɒlˈkeɪnəʊ/','火山'],['observe','/əbˈzɜːv/','观察'],['erupt','/ɪˈrʌpt/','喷发'],['violently','/ˈvaɪələntli/','猛烈地'],['liquid','/ˈlɪkwɪd/','液体的'],['escape','/ɪˈskeɪp/','逃跑']], notes:['spend one\'s lifetime doing 一生都在做。','set up 搭建。','just in time 及时。'], tags:['时间状语从句','一般过去时'], difficulty:4, summary:'波兰科学家塔齐耶夫一生研究火山，1948年他在刚果近距离观察基图罗火山喷发，拍下精彩照片后及时逃脱。', summaryEn:'Haroun Tazieff spent his lifetime studying volcanoes. In 1948 he set up camp near the erupting Kituro volcano in the Congo and took brilliant photographs before escaping just in time.' },
  { id:68, title:'Persistent', titleCn:'纠缠不休', text:['I crossed the street to avoid meeting him, but he saw me and came running towards me.','It was no use pretending that I had not seen him, so I waved to him.','I never enjoy meeting Nigel Dykes. He never has anything to do.','No matter how busy you are, he always insists on coming with you.','I had to think of a way of preventing him from following me around all morning.','"Hello, Nigel," I said. "Fancy meeting you here! He asked me how I was and then offered to buy me a drink."'], vocab:[['persistent','/pəˈsɪstənt/','纠缠不休的'],['avoid','/əˈvɔɪd/','避免'],['insist','/ɪnˈsɪst/','坚持'],['prevent','/prɪˈvent/','阻止'],['fancy','/ˈfænsi/','想不到'],['offer','/ˈɒfə/','提议']], notes:['it was no use pretending 假装……没有用。','insist on doing 坚持做某事。','prevent...from 阻止……做。'], tags:['动名词','宾语从句'], difficulty:3, summary:'作者在街上遇到总爱纠缠人的奈杰尔·戴克斯，他总是坚持要跟着别人，作者想方设法摆脱他。', summaryEn:'The writer tried to avoid meeting Nigel Dykes, who always insists on tagging along. Despite attempts to escape, Nigel followed and offered to buy a drink.' },
  { id:69, title:'But not murder!', titleCn:'并非谋杀！', text:['I was being tested for a driving licence for the third time.','I had been asked to drive in heavy traffic and had done so successfully.','After having been instructed to drive out of town, I began to acquire confidence.','Surely that time nothing would go wrong?','The examiner must have been pleased with my performance, for he smiled and said, "Mr. Eames, I am going to ask you a question."','"Suppose a child suddenly crossed the road in front of you. What would you do?"'], vocab:[['murder','/ˈmɜːdə/','谋杀'],['licence','/ˈlaɪsns/','执照'],['examiner','/ɪɡˈzæmɪnə/','考官'],['confidence','/ˈkɒnfɪdəns/','信心'],['performance','/pəˈfɔːməns/','表现'],['suppose','/səˈpəʊz/','假设']], notes:['be tested for 参加……考试。','be pleased with 对……满意。','suppose 假设。'], tags:['虚拟语气','被动语态'], difficulty:3, summary:'作者第三次考驾照，考官似乎很满意他的表现，然后突然问他如果一个孩子冲到车前该怎么办。', summaryEn:'Taking a driving test for the third time, the writer performed well. The examiner then asked what he would do if a child suddenly crossed the road.' },
  { id:70, title:'Red for danger', titleCn:'危险的红色', text:['During a bullfight, a drunk suddenly wandered into the middle of the ring.','The crowd began to shout, but the drunk was unaware of the danger.','The bull was busy with the matador at the time, but it suddenly caught sight of the drunk who was shouting rude remarks and waving a red cap.','Apparently sensitive to criticism, the bull forgot all about the matador and charged at the drunk.','The crowd suddenly grew quiet. The drunk, however, seemed quite sure of himself.','When the bull got close to him, he clumsily stepped aside to let it pass.'], vocab:[['bullfight','/ˈbʊlfaɪt/','斗牛'],['drunk','/drʌŋk/','醉汉'],['bull','/bʊl/','公牛'],['charge','/tʃɑːdʒ/','冲向'],['sensitive','/ˈsensətɪv/','敏感的'],['clumsily','/ˈklʌmzɪli/','笨拙地']], notes:['be unaware of 没有意识到。','catch sight of 看见。','charge at 向……冲去。'], tags:['时间状语从句','形容词短语'], difficulty:3, summary:'斗牛场上一个醉汉闯入，公牛看到他的红帽子后冲向他，醉汉笨拙地闪身躲过。', summaryEn:'A drunk wandered into a bullfight ring. The bull charged at him when it saw his red cap, but the drunk clumsily stepped aside to let it pass.' },
  { id:71, title:'A famous clock', titleCn:'一个著名的大钟', text:['When you visit London, one of the first things you will see is Big Ben, the famous clock which can be heard all over the world on the BBC.','If the Houses of Parliament had not been burned down in 1834, the great clock would never have been erected.','Big Ben takes its name from Sir Benjamin Hall who was responsible for the making of the clock when the new Houses of Parliament were being built.','It is not only of immense size, but is extremely accurate as well.','Officials from Greenwich Observatory have the clock checked twice a day.','On the BBC you can hear the clock when it is actually striking because microphones are connected to the clock tower.'], vocab:[['Parliament','/ˈpɑːləmənt/','议会'],['erect','/ɪˈrekt/','竖起'],['accurate','/ˈækjərət/','精确的'],['observatory','/əbˈzɜːvətri/','天文台'],['microphone','/ˈmaɪkrəfəʊn/','麦克风'],['tower','/ˈtaʊə/','塔']], notes:['take its name from 以……命名。','be responsible for 负责。','be connected to 连接到。'], tags:['虚拟语气','被动语态'], difficulty:4, summary:'大本钟以本杰明·霍尔爵士命名，不仅巨大而且极其精确，格林尼治天文台官员每天校验两次，BBC通过麦克风向全世界转播钟声。', summaryEn:'Big Ben, named after Sir Benjamin Hall, is immense and extremely accurate. It is checked twice daily and broadcast worldwide on the BBC through microphones in the clock tower.' },
  { id:72, title:'A car called Bluebird', titleCn:'名叫蓝鸟的汽车', text:['The great racing driver, Sir Malcolm Campbell, was the first man to drive at over 300 miles per hour.','He set up a new world record in September 1935 at Bonneville Salt Flats, Utah.','Bluebird, the car he was driving, had been specially built for him.','It was over 30 feet in length and had a 2,500-horsepower engine.','Although Campbell reached a speed of over 304 miles per hour, he had great difficulty in controlling the car because a tyre burst during the first run.','After his attempt, Campbell was disappointed to learn that his average speed had been 299 miles per hour.'], vocab:[['racing','/ˈreɪsɪŋ/','赛车'],['record','/ˈrekɔːd/','纪录'],['horsepower','/ˈhɔːspaʊə/','马力'],['tyre','/ˈtaɪə/','轮胎'],['burst','/bɜːst/','爆裂'],['average','/ˈævərɪdʒ/','平均的']], notes:['set up a new world record 创造新的世界纪录。','have great difficulty in 做某事有很大困难。','be disappointed to 得知……很失望。'], tags:['不定式','让步状语从句'], difficulty:4, summary:'赛车手马尔科姆·坎贝尔驾驶专门为他打造的蓝鸟汽车试图突破时速300英里的世界纪录，但因轮胎爆裂平均速度未达标。', summaryEn:'Sir Malcolm Campbell drove the specially built Bluebird car to break 300 mph, but a burst tyre caused difficulties. His average speed was recorded at 299 mph.' },
  { id:73, title:'The record-holder', titleCn:'纪录保持者', text:['Children who play truant from school are unimaginative.','A quiet day\'s fishing, or eight hours in a cinema seeing the same film over and over again, is usually as far as they get.','They have all been put to shame by a boy who, while playing truant, travelled 1,600 miles.','He hitchhiked to Dover, and towards evening he went into a boat to find somewhere to sleep.','When he woke up next morning, he discovered that the boat had, in the meantime, travelled to Calais.','No one noticed the boy as he crept off.'], vocab:[['record-holder','/ˈrekɔːd ˌhəʊldə/','纪录保持者'],['truant','/ˈtruːənt/','逃学'],['unimaginative','/ˌʌnɪˈmædʒɪnətɪv/','缺乏想象力的'],['hitchhike','/ˈhɪtʃhaɪk/','搭便车'],['creep','/kriːp/','蹑手蹑脚地走'],['shame','/ʃeɪm/','羞耻']], notes:['play truant 逃学。','put to shame 使……相形见绌。','in the meantime 与此同时。'], tags:['定语从句','时间状语从句'], difficulty:3, summary:'一个逃学的男孩搭便车到了多佛，在船上睡着后被带到了法国加莱，行程1600英里。', summaryEn:'A truant boy hitchhiked to Dover, fell asleep on a boat, and woke up in Calais, France, having travelled 1,600 miles and putting other truants to shame.' },
  { id:74, title:'Out of the limelight', titleCn:'舞台之外', text:['An ancient bus stopped by a dry river bed and a party of famous actors and actresses got off.','Dressed in dark glasses and old clothes, they had taken special precautions so that no one should recognize them.','But as they soon discovered, disguises can sometimes be too perfect.','"It\'s all right now," said the driver. "You can get off."','The actor who played the leading part in the play was one of the most famous actors in the world.','He had been told that a car would be sent for him, but he preferred to walk.'], vocab:[['limelight','/ˈlaɪmlaɪt/','公众注目的中心'],['precaution','/prɪˈkɔːʃn/','预防措施'],['recognize','/ˈrekəɡnaɪz/','认出'],['disguise','/dɪsˈɡaɪz/','伪装'],['leading','/ˈliːdɪŋ/','主角的'],['prefer','/prɪˈfɜː/','宁愿']], notes:['so that 以便。','take special precautions 采取特别的预防措施。','prefer to do 宁愿做。'], tags:['过去分词','目的状语从句'], difficulty:3, summary:'一群著名演员乔装打扮乘坐旧巴士外出，但伪装太完美反而惹了麻烦，他们不得不在干河床边下车。', summaryEn:'A group of famous actors dressed in disguise to avoid recognition. Their disguises were so perfect they caused unexpected problems when they stopped by a dry river bed.' },
  { id:75, title:'SOS', titleCn:'呼救信号', text:['When a light passenger plane flew off course some time ago, it crashed in the mountains and its pilot was killed.','The only passengers, a young woman and her two baby daughters, were unhurt.','It was the middle of winter. Snow lay thick on the ground.','The woman knew that the nearest village was miles away.','When it grew dark, she turned a suitcase into a bed and put the children inside it, covering them with all the clothes she could find.','During the night, it got terribly cold. The woman kept as near as she could to the children.'], vocab:[['passenger','/ˈpæsɪndʒə/','乘客'],['course','/kɔːs/','航线'],['pilot','/ˈpaɪlət/','飞行员'],['unhurt','/ʌnˈhɜːt/','未受伤的'],['suitcase','/ˈsuːtkeɪs/','手提箱'],['terribly','/ˈterəbli/','极其']], notes:['fly off course 偏离航线。','as near as she could 尽可能靠近。','cover...with 用……覆盖。'], tags:['时间状语从句','分词短语'], difficulty:4, summary:'一架小型客机偏离航线坠毁在山中，一名妇女和两个婴儿幸存，她在寒冬中用手提箱当床保护孩子过夜。', summaryEn:'A light plane crashed in the mountains. A young woman and her two baby daughters survived. She made a bed from a suitcase and kept the children warm through the freezing night.' },
  { id:76, title:'April Fools\' Day', titleCn:'愚人节', text:['"To end our special news bulletin," said the voice of the television announcer, "we are taking you to the macaroni fields of Calabria."','"You can see here the workers who have been busy picking macaroni for the last two weeks.","The macaroni crop this year is splendid.","It is being picked and dried in the hot sunshine.","The whole of Italy has enjoyed a macaroni crop of over 350,000 tons this year.","Of course, many people will believe this report, but in actual fact, the spaghetti harvest in Italy is only a joke."'], vocab:[['bulletin','/ˈbʊlətɪn/','新闻简报'],['announcer','/əˈnaʊnsə/','播音员'],['macaroni','/ˌmækəˈrəʊni/','通心粉'],['splendid','/ˈsplendɪd/','极好的'],['harvest','/ˈhɑːvɪst/','收成'],['spaghetti','/spəˈɡeti/','意大利面']], notes:['April Fools\' Day 愚人节。','in actual fact 事实上。','be busy doing 忙于做。'], tags:['被动语态','现在完成时'], difficulty:3, summary:'BBC愚人节新闻报道了意大利通心粉大丰收，实际上这是个经典的愚人节玩笑，许多人信以为真。', summaryEn:'In a famous April Fools\' Day joke, BBC news reported a bumper macaroni harvest in Italy. Many people believed the report about the spaghetti crop.' },
  { id:77, title:'A successful operation', titleCn:'成功的手术', text:['The mummy of an Egyptian woman who died in 800 B.C. has just had an operation.','The mummy is that of Shepenmut who was once a singer in the Temple of Thebes.','As there were strange marks on the X-ray plates taken of the mummy, doctors have been trying to find out whether the woman died of a rare disease.','The only way to do this was to operate.','The operation was a success and the mummy survived.','After the operation, the doctors were surprised to find a small wax figure of the god Duamutef inside the mummy.'], vocab:[['mummy','/ˈmʌmi/','木乃伊'],['Egyptian','/ɪˈdʒɪpʃn/','埃及的'],['temple','/ˈtempl/','神庙'],['disease','/dɪˈziːz/','疾病'],['operate','/ˈɒpəreɪt/','做手术'],['wax','/wæks/','蜡']], notes:['die of 死于。','the only way to do this 做这件事的唯一方法。','be surprised to 惊讶地发现。'], tags:['定语从句','过去完成时'], difficulty:4, summary:'一具公元前800年的埃及女木乃伊接受了手术，医生在她体内发现了小蜡像，手术成功，木乃伊安然无恙。', summaryEn:'An Egyptian mummy dating to 800 B.C. underwent an operation. Doctors found a small wax figure of a god inside. The operation was successful and the mummy survived.' },
  { id:78, title:'The last one?', titleCn:'最后一枝吗？', text:['After reading an article entitled "Cigarette Smoking and Your Health", I lit a cigarette to calm my nerves.','I smoked with concentration and pleasure as I was sure that this would be my last one.','For a whole week I did not smoke at all and during this time, my wife suffered terribly.','I had all the usual symptoms of someone giving up smoking: a bad temper and an enormous appetite.','My friends kept on offering me cigarettes and cigars.','They made no effort to hide their amusement whenever I produced a packet of sweets from my pocket.'], vocab:[['cigarette','/ˌsɪɡəˈret/','香烟'],['entitle','/ɪnˈtaɪtl/','标题为'],['nerve','/nɜːv/','神经'],['symptom','/ˈsɪmptəm/','症状'],['temper','/ˈtempə/','脾气'],['enormous','/ɪˈnɔːməs/','极大的']], notes:['calm my nerves 使神经平静。','give up smoking 戒烟。','keep on doing 继续做。'], tags:['现在分词','时间状语从句'], difficulty:3, summary:'作者读了吸烟有害健康的文章后决定戒烟，戒烟期间脾气暴躁、食欲大增，朋友不断递烟取笑他。', summaryEn:'After reading about smoking and health, the writer tried to quit. He suffered bad temper and enormous appetite while friends kept offering cigarettes and laughing at his sweets.' },
  { id:79, title:'By air', titleCn:'乘飞机', text:['I used to travel by air a great deal when I was a boy.','My parents used to live in South America and I used to fly there from Europe in the holidays.','A flight attendant would take charge of me and I never had an unpleasant experience.','I am used to travelling by air and only on one occasion have I ever felt frightened.','After taking off, we were flying low over the city and slowly gaining height, when the plane suddenly turned round and flew back to the airport.','While we were waiting to land, a flight attendant told us to keep calm.'], vocab:[['flight','/flaɪt/','飞行'],['attendant','/əˈtendənt/','服务员'],['occasion','/əˈkeɪʒn/','场合'],['frightened','/ˈfraɪtnd/','害怕的'],['gain','/ɡeɪn/','获得'],['calm','/kɑːm/','镇静的']], notes:['a great deal 大量。','be used to doing 习惯于做。','take charge of 负责照顾。'], tags:['used to','过去进行时'], difficulty:3, summary:'作者小时候常乘飞机旅行，习惯后只有一次感到害怕——飞机起飞后不久便掉头返航。', summaryEn:'The writer used to travel by air as a boy and was accustomed to flying. Only once did he feel frightened when the plane turned back to the airport shortly after takeoff.' },
  { id:80, title:'The Crystal Palace', titleCn:'水晶宫', text:['Perhaps the most extraordinary building of the nineteenth century was the Crystal Palace, which was built in Hyde Park for the Great Exhibition of 1851.','The Crystal Palace was different from all other buildings in the world, for it was made of iron and glass.','It was one of the biggest buildings of all time and a lot of people from many countries came to see it.','A great many goods were sent to the exhibition from various parts of the world.','There was also a great deal of machinery on display.','The most wonderful piece of machinery on show was Nasmyth\'s steam hammer.'], vocab:[['crystal','/ˈkrɪstl/','水晶'],['extraordinary','/ɪkˈstrɔːdnri/','非凡的'],['exhibition','/ˌeksɪˈbɪʃn/','展览会'],['machinery','/məˈʃiːnəri/','机器'],['iron','/ˈaɪən/','铁'],['display','/dɪˈspleɪ/','展示']], notes:['be different from 与……不同。','be made of 由……制成。','a great deal of 大量的。'], tags:['被动语态','定语从句'], difficulty:4, summary:'水晶宫是为1851年世博会在海德公园建造的非凡建筑，由铁和玻璃制成，展示了来自世界各地的大量商品和机器。', summaryEn:'The Crystal Palace, built in Hyde Park for the 1851 Great Exhibition, was made of iron and glass. It displayed goods and machinery from around the world.' },
  { id:81, title:'Escape', titleCn:'逃脱', text:['The prisoner of war had been planning his escape for a long time.','He had dug a tunnel from his cell to the outside, and it had taken him several months.','When he had completed the tunnel, he crawled through it and came up in the middle of a field.','It was dark and he could not see where he was going.','He walked for several hours until he came to a farmhouse.','He knocked on the door and asked if he could stay the night.'], vocab:[['prisoner','/ˈprɪznə/','囚犯'],['escape','/ɪˈskeɪp/','逃跑'],['tunnel','/ˈtʌnl/','隧道'],['cell','/sel/','牢房'],['crawl','/krɔːl/','爬行'],['farmhouse','/ˈfɑːmhaʊs/','农舍']], notes:['plan one\'s escape 计划逃跑。','come up 出来。','stay the night 过夜。'], tags:['过去完成时','间接引语'], difficulty:3, summary:'一名战俘挖了几个月的隧道逃出牢房，走了几个小时来到一家农舍请求借宿过夜。', summaryEn:'A prisoner of war dug a tunnel from his cell over several months. He crawled through and walked for hours until he reached a farmhouse where he asked to stay the night.' },
  { id:82, title:'Monster or fish?', titleCn:'是妖还是鱼？', text:['Fishermen and sailors sometimes claim to have seen monsters in the sea.','Though people have often laughed at stories told by seamen, it is now known that many of these "monsters" which have at times been sighted are simply strange fish.','Occasionally, unusual creatures are washed to the shore, but they are rarely caught out at sea.','Some time ago, however, a peculiar fish was caught near Madagascar.','A small fishing boat was carried miles out to sea by the powerful fish as it pulled on the line.','Realizing what had happened, the fisherman made every effort not to damage it.'], vocab:[['monster','/ˈmɒnstə/','怪物'],['sailor','/ˈseɪlə/','水手'],['creature','/ˈkriːtʃə/','生物'],['peculiar','/pɪˈkjuːliə/','奇怪的'],['powerful','/ˈpaʊəfl/','强大的'],['damage','/ˈdæmɪdʒ/','损坏']], notes:['laugh at 嘲笑。','make every effort to 尽一切努力。','wash to the shore 被冲上岸。'], tags:['被动语态','现在分词'], difficulty:4, summary:'渔夫和水手声称看到海怪，后来在马达加斯加附近捕到一条奇特的大鱼，它把小渔船拖出了好几英里。', summaryEn:'Fishermen claim to have seen sea monsters. A peculiar fish caught near Madagascar pulled a small fishing boat miles out to sea before being carefully hauled in.' },
  { id:83, title:'After the elections', titleCn:'大选之后', text:['The former Prime Minister, Mr. Wentworth Lane, was defeated in the recent elections.','He is now retiring from political life and has gone abroad.','My friend, Patrick, has always been a fanatical opponent of Mr. Lane\'s Radical Progressive Party.','After the elections, Patrick went to the former Prime Minister\'s house.','When he asked if Mr. Lane lived there, the policeman on duty told him that since his defeat, the ex-Prime Minister had gone abroad.','"He won\'t return for a long time," the policeman added.'], vocab:[['election','/ɪˈlekʃn/','选举'],['defeat','/dɪˈfiːt/','击败'],['former','/ˈfɔːmə/','前任的'],['opponent','/əˈpəʊnənt/','反对者'],['progressive','/prəˈɡresɪv/','进步的'],['duty','/ˈdjuːti/','值班']], notes:['retire from 从……退休。','on duty 值班。','fanatical opponent 狂热的反对者。'], tags:['过去完成时','间接引语'], difficulty:3, summary:'前首相在大选中落败后出国了，帕特里克去他家拜访时被告知他很长时间不会回来。', summaryEn:'Former Prime Minister Mr. Lane was defeated in the elections and went abroad. When Patrick visited his house, a policeman told him the ex-PM would not return for a long time.' },
  { id:84, title:'On strike', titleCn:'罢工', text:['Busmen have decided to go on strike next week.','The strike is due to begin on Tuesday. No one knows how long it will last.','The busmen have stated that the strike will continue until general agreement is reached about pay and working conditions.','Most people believe that the strike will last for at least a week.','Many bus owners have volunteered to drive buses during the strike, but all of them have so far been unable to pass the test.','The public is strongly against the strike.'], vocab:[['strike','/straɪk/','罢工'],['due','/djuː/','预定的'],['agreement','/əˈɡriːmənt/','协议'],['condition','/kənˈdɪʃn/','条件'],['volunteer','/ˌvɒlənˈtɪə/','自愿'],['public','/ˈpʌblɪk/','公众']], notes:['go on strike 举行罢工。','be due to 预定。','at least 至少。'], tags:['将来时态','间接引语'], difficulty:3, summary:'公交司机决定下周罢工，要求改善工资和工作条件，许多车主自愿驾车但都未能通过考试。', summaryEn:'Busmen decided to strike for better pay and working conditions. Volunteer bus owners were unable to pass the driving test, and the public strongly opposed the strike.' },
  { id:85, title:'Never too old to learn', titleCn:'活到老学到老', text:['I have just received a letter from my old school informing me that my former headmaster, Mr. Stuart Page, will be retiring next week.','Pupils of the school, old and new, will be sending him a present to mark the occasion.','All those who have contributed to the fund will sign their names in a large album which will be sent to the headmaster\'s home.','We shall all remember Mr. Page for his patience and understanding and for the kindly encouragement he gave us when we went to the school.','A great many former pupils will be attending a farewell dinner in his honour next Thursday.','It is a curious coincidence that the day he is retiring is his birthday.'], vocab:[['inform','/ɪnˈfɔːm/','通知'],['headmaster','/ˌhedˈmɑːstə/','校长'],['occasion','/əˈkeɪʒn/','场合'],['contribute','/kənˈtrɪbjuːt/','捐献'],['patience','/ˈpeɪʃns/','耐心'],['coincidence','/kəʊˈɪnsɪdəns/','巧合']], notes:['inform sb. that 通知某人。','contribute to 为……做贡献。','in his honour 为向他表示敬意。'], tags:['将来进行时','定语从句'], difficulty:4, summary:'作者收到母校来信，得知老校长下周退休，校友们将赠送礼物并举办告别晚宴，巧合的是退休日恰是他的生日。', summaryEn:'The writer learned that former headmaster Mr. Page is retiring. Pupils old and new will send a present and attend a farewell dinner. His retirement day coincides with his birthday.' },
  { id:86, title:'Out of control', titleCn:'失控', text:['As the man tried to swing the speedboat round, the steering wheel came away in his hands.','He waved desperately to his companion, who had been water skiing for the last fifteen minutes.','Both men had hardly had time to realize what was happening when they were thrown violently into the sea.','The speedboat had struck a buoy, but it continued to move very quickly across the water.','Both men had just begun to swim towards the shore, when they noticed with dismay that the speedboat was moving in a circle.','It now came straight towards them at tremendous speed.'], vocab:[['control','/kənˈtrəʊl/','控制'],['steering','/ˈstɪərɪŋ/','转向'],['desperately','/ˈdespərətli/','绝望地'],['companion','/kəmˈpæniən/','同伴'],['buoy','/bɔɪ/','浮标'],['tremendous','/trɪˈmendəs/','极大的']], notes:['come away 脱落。','throw into 扔进。','at tremendous speed 以极快的速度。'], tags:['过去完成时','时间状语从句'], difficulty:4, summary:'驾驶快艇时方向盘脱落，船撞上浮标后失控地在海上打转，两个男人被甩入海中，快艇又朝他们飞驰而来。', summaryEn:'The steering wheel came off a speedboat, which struck a buoy and went out of control. Both men were thrown into the sea and the boat circled back towards them at tremendous speed.' },
  { id:87, title:'A perfect alibi', titleCn:'极好的不在犯罪现场的证据', text:['"My story is simple," said the accused man. "I was sitting in a restaurant when a robbery took place."','"I was watching a movie at the time," he added.','"Can you prove that?" asked the judge.','"I can prove it, Your Honour," the man said. "I was at the cinema with my wife."','"And did your wife see the film?" asked the judge.','"No," said the accused, "she was sitting beside me and she slept through the whole film."'], vocab:[['alibi','/ˈæləbaɪ/','不在场证明'],['accused','/əˈkjuːzd/','被告的'],['robbery','/ˈrɒbəri/','抢劫'],['prove','/pruːv/','证明'],['judge','/dʒʌdʒ/','法官'],['honour','/ˈɒnə/','阁下']], notes:['take place 发生。','at the time 当时。','sleep through 睡着看完。'], tags:['间接引语','过去进行时'], difficulty:3, summary:'被告声称案发时在电影院看电影，但当法官问他妻子是否也看了电影时，他说妻子一直在睡觉。', summaryEn:'The accused claimed he was at the cinema during a robbery. When asked if his wife saw the film, he admitted she had slept through the whole thing, weakening his alibi.' },
  { id:88, title:'A slip of the tongue', titleCn:'口误', text:['People will do anything to see a free show, even if it is a bad one.','When the show was over, the comedian turned to the audience and asked if anyone wanted to see him do a trick.','"I\'m going to need a volunteer from the audience," he said. "Who will volunteer?"','A man in the front row put up his hand. The comedian called him up on to the stage.','"Now, sir," he said, "I\'m going to ask you a very simple question."','The man was so nervous that he could not remember his own name.'], vocab:[['slip','/slɪp/','失误'],['comedian','/kəˈmiːdiən/','喜剧演员'],['volunteer','/ˌvɒlənˈtɪə/','志愿者'],['audience','/ˈɔːdiəns/','观众'],['stage','/steɪdʒ/','舞台'],['nervous','/ˈnɜːvəs/','紧张的']], notes:['even if 即使。','put up one\'s hand 举手。','so...that 如此……以至于。'], tags:['结果状语从句','目的状语从句'], difficulty:3, summary:'喜剧演员请观众上台配合表演，一位自愿上台的观众因为太紧张连自己的名字都记不起来了。', summaryEn:'A comedian asked for a volunteer from the audience. A man from the front row was so nervous on stage that he could not even remember his own name.' },
  { id:89, title:'A noble gift', titleCn:'崇高的礼物', text:['The Statue of Liberty was presented to the United States of America in the nineteenth century by the people of France.','The great statue, which was designed by the sculptor Auguste Bartholdi, took ten years to complete.','The actual figure was made of copper supported by a metal framework which had been specially constructed by Eiffel.','Before it could be transported to the United States, a site had to be found for it and a pedestal had to be built.','The site chosen was an island at the entrance of New York Harbour.','The statue was assembled in Paris and shipped to America in crates.'], vocab:[['statue','/ˈstætʃuː/','雕像'],['liberty','/ˈlɪbəti/','自由'],['sculptor','/ˈskʌlptə/','雕塑家'],['copper','/ˈkɒpə/','铜'],['framework','/ˈfreɪmwɜːk/','框架'],['pedestal','/ˈpedɪstl/','底座']], notes:['be presented to 被赠送给。','take ten years to complete 花了十年完成。','at the entrance of 在……的入口处。'], tags:['被动语态','定语从句'], difficulty:4, summary:'自由女神像是法国人民在19世纪赠送给美国的，由雕塑家巴托尔迪设计，铜质雕像由埃菲尔建造的金属框架支撑。', summaryEn:'The Statue of Liberty was a gift from France to America. Designed by Bartholdi with an Eiffel framework, it was assembled in Paris and shipped in crates to New York.' },
  { id:90, title:'What\'s for supper?', titleCn:'晚餐吃什么？', text:['Fish and chips has always been a favourite dish in Britain, but as the oceans have been overfished, fish has become more and more expensive.','So it comes as a surprise to learn that giant fish are terrifying the divers on North Sea oil rigs.','Oil rigs have to be repaired frequently and divers are often sent down to examine the repairs.','When they are under the water, divers are sometimes attacked by giant fish.','These fish, which are called batfish, are not dangerous to human beings.','However, their sharp teeth can do a great deal of damage to rubber diving suits.'], vocab:[['chip','/tʃɪp/','薯条'],['overfish','/ˌəʊvəˈfɪʃ/','过度捕捞'],['terrify','/ˈterɪfaɪ/','恐吓'],['diver','/ˈdaɪvə/','潜水员'],['giant','/ˈdʒaɪənt/','巨大的'],['rubber','/ˈrʌbə/','橡胶的']], notes:['it comes as a surprise to learn 得知……令人吃惊。','be dangerous to 对……有危险。','do damage to 对……造成损害。'], tags:['现在完成时','定语从句'], difficulty:4, summary:'由于海洋过度捕捞，鱼价飞涨，但北海石油钻井平台的潜水员却被巨型蝙蝠鱼骚扰，它们的利齿能严重损坏橡胶潜水服。', summaryEn:'As oceans are overfished, fish prices rise. Meanwhile, giant batfish terrorize divers at North Sea oil rigs, damaging their rubber diving suits with sharp teeth.' },
  { id:91, title:'Three men in a basket', titleCn:'三人同篮', text:['A pilot noticed a balloon which seemed to be making for a Royal Air Force station nearby.','He reported this and the station officer sent a helicopter to investigate.','The helicopter crew reported that a man was hanging from the basket of the balloon and there was another man in the basket.','The officer sent three soldiers to the spot with a large net.','When the balloon landed, the soldiers rushed forward, but before they could grab the basket, the balloon rose again.','It finally came down in a ploughed field, and the soldiers ran after it.'], vocab:[['balloon','/bəˈluːn/','气球'],['helicopter','/ˈhelɪkɒptə/','直升机'],['investigate','/ɪnˈvestɪɡeɪt/','调查'],['crew','/kruː/','机组人员'],['grab','/ɡræb/','抓住'],['ploughed','/plaʊd/','犁过的']], notes:['make for 向……移动。','hang from 悬挂。','run after 追赶。'], tags:['定语从句','时间状语从句'], difficulty:3, summary:'飞行员发现一个气球飞向空军基地，直升机调查后发现气球篮里有人，士兵们追赶气球直到它降落在一块犁过的田里。', summaryEn:'A pilot spotted a balloon heading for an RAF station. A helicopter crew found men in the basket. Soldiers chased the balloon until it landed in a ploughed field.' },
  { id:92, title:'Asking for trouble', titleCn:'自找麻烦', text:['It must have been about two in the morning when I returned home.','I tried to wake up my wife by ringing the doorbell, but she was fast asleep.','So I got a ladder from the shed in the garden, put it against the wall, and began climbing towards the bedroom window.','I was almost there when a sarcastic voice below said, "I don\'t think the windows need cleaning at this time of the night."','Looking down, I nearly fell off the ladder when I saw a policeman.','I immediately regretted answering in the way I did.'], vocab:[['ladder','/ˈlædə/','梯子'],['sarcastic','/sɑːˈkæstɪk/','讽刺的'],['shed','/ʃed/','棚子'],['immediately','/ɪˈmiːdiətli/','立即'],['regret','/rɪˈɡret/','后悔'],['fast','/fɑːst/','熟睡地']], notes:['fast asleep 熟睡。','fall off 从……摔下。','regret doing 后悔做了某事。'], tags:['分词短语','时间状语从句'], difficulty:3, summary:'作者深夜回家叫不醒妻子，拿梯子爬向卧室窗户时被警察发现，警察讽刺说不需要在这个时候擦窗户。', summaryEn:'The writer came home late and tried to climb a ladder to his bedroom window. A policeman spotted him and sarcastically remarked that windows didn\'t need cleaning at that hour.' },
  { id:93, title:'A noble gift', titleCn:'崇高的礼物', text:['The great bell of the clock of the Houses of Parliament, known as Big Ben, has become one of the most famous landmarks of London.','It was named after Sir Benjamin Hall, the first Commissioner of Works.','When the Houses of Parliament were being rebuilt after the fire of 1834, it was decided that a new clock tower should be built.','Sir Benjamin Hall was the man who was in charge of the project.','The tower was completed in 1858 and the clock started on May 31 of that year.','Big Ben has rarely gone wrong, but it did once stop when a heavy bucket was hung on the pendulum.'], vocab:[['landmark','/ˈlændmɑːk/','地标'],['commissioner','/kəˈmɪʃənə/','专员'],['project','/ˈprɒdʒekt/','项目'],['pendulum','/ˈpendjələm/','钟摆'],['rarely','/ˈreəli/','很少'],['bucket','/ˈbʌkɪt/','桶']], notes:['be named after 以……命名。','be in charge of 负责。','go wrong 出故障。'], tags:['被动语态','定语从句'], difficulty:3, summary:'大本钟以本杰明·霍尔爵士命名，1858年建成后极少出错，但曾经因钟摆上挂了一个桶而停走。', summaryEn:'Big Ben, named after Sir Benjamin Hall, was completed in 1858 and has rarely gone wrong. It once stopped when a heavy bucket was hung on the pendulum.' },
  { id:94, title:'Future champions', titleCn:'未来的冠军', text:['Experiments have proved that children can be taught to swim at a very early age.','At a special swimming pool in Los Angeles, children become expert at holding their breath under water even before they can walk.','Babies of two months old do not appear to be reluctant to enter the water.','It is not long before they are so accustomed to swimming that they can pick up weights from the floor of the pool.','A game that is very popular with these young swimmers is the underwater tricycle race.','Tricycles are lined up on the floor of the pool seven feet under water.'], vocab:[['champion','/ˈtʃæmpiən/','冠军'],['experiment','/ɪkˈsperɪmənt/','实验'],['reluctant','/rɪˈlʌktənt/','不情愿的'],['accustomed','/əˈkʌstəmd/','习惯的'],['tricycle','/ˈtraɪsɪkl/','三轮车'],['underwater','/ˌʌndəˈwɔːtə/','水下的']], notes:['be reluctant to 不情愿做。','be accustomed to 习惯于。','pick up 拾起。'], tags:['被动语态','结果状语从句'], difficulty:4, summary:'实验证明幼儿可以在很小的年纪学游泳，洛杉矶的游泳池里两个月大的婴儿就已习惯水中活动，还能进行水下三轮车比赛。', summaryEn:'Experiments prove children can learn to swim very early. Babies as young as two months become accustomed to water, and young swimmers enjoy underwater tricycle races.' },
  { id:95, title:'A fantasy', titleCn:'纯属虚构', text:['When the Ambassador of Escalot returned home for lunch, his wife was very excited.','"You had a very good journey, didn\'t you, dear?" she asked.','"Yes, it was quite a good journey," the Ambassador replied.','His wife then told him that she had been to the airport to meet him. "The flight was on time," she said.','"It landed twenty minutes ago."','The Ambassador looked very surprised. "That\'s impossible," he said. "I was on the same flight and it has not arrived yet."'], vocab:[['fantasy','/ˈfæntəsi/','幻想'],['ambassador','/æmˈbæsədə/','大使'],['journey','/ˈdʒɜːni/','旅程'],['flight','/flaɪt/','航班'],['impossible','/ɪmˈpɒsəbl/','不可能的'],['excited','/ɪkˈsaɪtɪd/','兴奋的']], notes:['on time 准时。','quite a good 相当好的。','look surprised 看起来很惊讶。'], tags:['间接引语','过去完成时'], difficulty:3, summary:'大使夫人去机场接丈夫，说航班已到，但大使说他就在那架飞机上而飞机还未到达——这纯属虚构。', summaryEn:'The Ambassador\'s wife said she had met his flight which landed twenty minutes ago, but the Ambassador said he was on that flight and it hadn\'t arrived yet. A fantasy indeed.' },
  { id:96, title:'The dead return', titleCn:'亡灵归来', text:['A Festival for the Dead is held once a year in Japan.','This festival is a cheerful occasion, for on this day, the dead are said to return to their homes and they are welcomed by the living.','As they are expected to be hungry after their long journey, food is laid out for them.','Specially made lanterns are hung outside each house to help the dead to find their way.','All night long, people dance and sing. In the early morning, the food that had been laid out for the dead is thrown into a river or into the sea.','In towns that are near the sea, the tiny lanterns which had been hung in the streets the night before are placed into the water.'], vocab:[['festival','/ˈfestɪvl/','节日'],['cheerful','/ˈtʃɪəfl/','欢乐的'],['occasion','/əˈkeɪʒn/','场合'],['lantern','/ˈlæntən/','灯笼'],['journey','/ˈdʒɜːni/','旅程'],['living','/ˈlɪvɪŋ/','活着的人']], notes:['be said to 据说。','lay out 摆出。','all night long 整晚。'], tags:['被动语态','定语从句'], difficulty:4, summary:'日本每年举办亡灵节，据说死者在这一天回家，人们摆出食物、挂灯笼为亡灵引路，第二天将食物扔进河海。', summaryEn:'In Japan, the Festival for the Dead welcomes spirits home once a year. Food is laid out, lanterns are hung, and people dance all night. The next morning, offerings are thrown into water.' },
];

function lessonToTs(l) {
  const vocabStr = l.vocab.map(v => `      { word: '${esc(v[0])}', phonetic: '${esc(v[1])}', meaning: '${esc(v[2])}' }`).join(',\n');
  const notesStr = l.notes.map(n => `      '${esc(n)}'`).join(',\n');
  const tagsStr = l.tags.map(t => `'${esc(t)}'`).join(', ');
  return `  {
    id: ${l.id},
    title: '${esc(l.title)}',
    titleCn: '${esc(l.titleCn)}',
    text: [
${l.text.map(t => `      '${esc(t)}'`).join(',\n')}
    ],
    textCn: [
${l.text.map(() => `      ''`).join(',\n')}
    ],
    vocabulary: [
${vocabStr}
    ],
    notes: [
${notesStr}
    ],
    tags: [${tagsStr}],
    difficulty: ${l.difficulty},
    summary: '${esc(l.summary)}',
    summaryEn: '${esc(l.summaryEn)}',
  }`;
}

let insertPos = content.indexOf('\r\n\r\nexport default book2');
if (insertPos === -1) insertPos = content.indexOf('\n\nexport default book2');
if (insertPos === -1) { const ep = content.lastIndexOf('export default book2'); insertPos = content.lastIndexOf(']', ep); }
if (insertPos === -1) { console.error('Could not find insertion point'); process.exit(1); }
const newLessons = lessons.map(lessonToTs).join(',\n');
content = content.slice(0, insertPos) + ',\n' + newLessons + '\n' + content.slice(insertPos);
fs.writeFileSync(filePath, content, 'utf-8');
console.log(`Added ${lessons.length} lessons to book2.ts`);
